/* Tile 3 rises over tile 2; the dashboard assembles and waits for review. */
const { seg, eio, lerp } = kit;
const RISE = 0.65, PLAY = 0.5;
kit.scene('build', {
  init(kit) {
    kit.stage.append(kit.h('<div class="ground"></div>'));
    this.t1 = window.HWF.tile(kit, 0, 3);
    window.HWF.cover(this.t1, 1);
    this.t2 = window.HWF.tile(kit, 1, 3.5);
    this.t3 = window.HWF.tile(kit, 2, 0);
    window.HWF.mark(kit, 'build');   /* the wordmark, where the intro left it */
  },
  render(t) {
    const p = eio(seg(t, 0, RISE));
    this.t2.s.transform = 'scale(' + lerp(1.0117, 0.97, p).toFixed(4) + ')';
    this.t2.shade.opacity = (0.035 * p).toFixed(4);
    this.t3.s.transform = 'translateY(' + lerp(1080 - 104, 0, p).toFixed(1) + 'px) scale(' + (1 + 0.0025 * Math.max(0, t - RISE)).toFixed(4) + ')';
    this.t3.scene.render(Math.max(0, t - PLAY));
  },
});
